#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    const long long MOD = 1000000007LL;
    int n = (int)readInt();
    long long left = readInt(), right = readInt();
    // Only values <= n can matter: a subsequence of length <= n has MEX <= n.
    vector<int> counts(n + 1, 0);
    for (int i = 0; i < n; i++) {
        long long v = readInt();
        if (v <= n) counts[v]++;
    }
    vector<long long> powers(n + 1, 1);
    for (int i = 1; i <= n; i++) powers[i] = powers[i - 1] * 2 % MOD;
    long long answer = 0, product = 1;
    int remaining = n;
    long long top = min<long long>(n, right);
    for (long long mex = 0; mex <= top; mex++) {
        int count = counts[mex];
        remaining -= count;
        // MEX == mex: at least one of each smaller value, no copy of mex, anything larger.
        if (mex >= left) answer = (answer + product * powers[remaining]) % MOD;
        product = product * ((powers[count] - 1 + MOD) % MOD) % MOD;
    }
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1000000007L;
        int n = nextInt();
        long left = nextLong(), right = nextLong();
        int[] counts = new int[n + 1];
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            if (v <= n) counts[(int) v]++;
        }
        long[] powers = new long[n + 1];
        powers[0] = 1;
        for (int i = 1; i <= n; i++) powers[i] = powers[i - 1] * 2 % MOD;
        long answer = 0, product = 1;
        int remaining = n;
        long top = Math.min(n, right);
        for (int mex = 0; mex <= top; mex++) {
            int count = counts[mex];
            remaining -= count;
            if (mex >= left) answer = (answer + product * powers[remaining]) % MOD;
            product = product * ((powers[count] - 1 + MOD) % MOD) % MOD;
        }
        System.out.println(answer);
    }
}
